package policy; import core.PortRange;import java.util.LinkedHashMap;import java.util.Map; public final class FirewallRule{private String chain="INPUT";private String action="ACCEPT";private String protocol="any";private String source="any";private String destination="any";private PortRange destinationPort=PortRange.any();private PortRange sourcePort=PortRange.any();private final Map<String,String>attributes=new LinkedHashMap<>();public String chain(){return chain;}public void chain(String v){chain=v;}public String action(){return action;}public void action(String v){action=v;}public String protocol(){return protocol;}public void protocol(String v){protocol=v;}public String source(){return source;}public void source(String v){source=v;}public String destination(){return destination;}public void destination(String v){destination=v;}public PortRange destinationPort(){return destinationPort;}public void destinationPort(PortRange v){destinationPort=v;}public PortRange sourcePort(){return sourcePort;}public void sourcePort(PortRange v){sourcePort=v;}public Map<String,String> attributes(){return attributes;}public String key(){return chain+'|'+protocol+'|'+source+'|'+destination+'|'+sourcePort+'|'+destinationPort+'|'+action;}}
